import{_ as r,l as t,o as a,c as i,v as o,p as l,x as d,d as s,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"数组与指针衰减","description":"","frontmatter":{"title":"数组与指针衰减","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/array-decay.md","filePath":"cs/array-decay.md","lastUpdated":1789023840000}'),E={name:"cs/array-decay.md"};function h(A,e,m,B,_,f){const c=t("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="数组与指针衰减" tabindex="-1">数组与指针衰减 <a class="header-anchor" href="#数组与指针衰减" aria-label="Permalink to &quot;数组与指针衰减&quot;">​</a></h1><div class="epigraph"><p>数组是一块连续的对象；在多数表达式里，它的名字会变成指向第一个元素的指针——长度信息在这一步丢掉。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/pointer-alias">指针与别名</a>钉死了：指针是对象地址，可以制造共享视图。本课不重讲别名，也不从「数组是对象」的数学定义另起。缺口是：声明 <code>int a[10]</code> 得到的是数组对象，<strong>为什么 <code>a</code> 常常用起来像指针，而 <code>sizeof(a)</code> 又不是指针的大小</strong>？传参时长度如何丢失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组对象占连续 <code>n</code> 个元素的存储，下标 <code>a[i]</code> 定义为 <code>*(a+i)</code>。在需要指针的上下文里，数组名衰减为指向首元素的指针。函数参数写成 <code>int a[]</code> 或 <code>int *a</code> 对调用方是同一件事：传入的是地址，不是数组拷贝。缺口因此不是下标语法，而是<strong>对象与衰减后的指针不是同一种东西</strong>——长度只活在数组类型里，一衰减就没了。</p><p>这解释了为何 C 函数不能靠参数类型恢复 <code>n</code>，必须另传长度或约定哨兵。也解释了为何嵌套数组、指针数组、指向数组的指针三种声明不能靠语感互换。本课只处理一维衰减；结构体里嵌数组、多维布局留给<a href="/cs/struct-layout">结构体内存布局</a>。</p><h3 id="a-与-a-不是同一类指针" tabindex="-1"><code>&amp;a</code> 与 <code>a</code> 不是同一类指针 <a class="header-anchor" href="#a-与-a-不是同一类指针" aria-label="Permalink to &quot;`&amp;a` 与 `a` 不是同一类指针&quot;">​</a></h3><p><code>a</code> 衰减后类型是「指向元素」；<code>&amp;a</code> 是「指向整个数组」，步长是整个数组的大小。两者数值上常常相同，加法一次之后就分叉。把它们当成「都是首地址」会在指针算术里越界而不自知。<code>sizeof</code> 对数组给出字节数，对衰减后的指针给出指针宽度——同一记号在不同上下文量的是不同对象。</p><p><span class="marginnote">K&amp;R 把数组与指针的互换写成 C 的核心习惯，同时警告：作为函数参数时数组已经不是数组。ISO C 把衰减写成表达式转换规则，例外是 <code>sizeof</code>、<code>_Alignof</code> 与 <code>&amp;</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 <code>T a[N]</code>：对象大小 <code>N * sizeof(T)</code>，对齐随 <code>T</code>。表达式 <code>a</code> 在非常见例外下变成 <code>(T *)&amp;a[0]</code>。<code>a[i]</code> 与 <code>i[a]</code> 因加法交换而合法，但本课不提倡后者。字符串字面量有静态数组类型，传给 <code>char *</code> 时同样衰减；改字面量是 UB。</p>',11)),(a(),l(p,null,{default:d(()=>[n(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E6%95%B0%E7%BB%84%E5%AF%B9%E8%B1%A1%20a%20%E9%95%BF%E5%BA%A6%E4%B8%BA%20N%22%5D%20--%3E%20DECAY%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%E9%87%8C%E8%A1%B0%E5%87%8F%E6%88%90%E9%A6%96%E5%85%83%E7%B4%A0%E6%8C%87%E9%92%88%22%5D%0A%20%20DECAY%20--%3E%20CALL%5B%22%E4%BD%9C%E4%B8%BA%E5%8F%82%E6%95%B0%E4%BC%A0%E5%85%A5%EF%BC%9A%E5%8F%AA%E5%89%A9%E5%9C%B0%E5%9D%80%22%5D%0A%20%20ARR%20--%3E%20SIZEOF%5B%22sizeof%20%E4%BB%8D%E7%9C%8B%E8%A7%81%20N%22%5D%0A%20%20CALL%20--%3E%20LOST%5B%22callee%20%E4%B8%8D%E5%86%8D%E7%9F%A5%E9%81%93%20N%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>指针算术：<code>p+1</code> 跳过一个元素，不是一个字节（除非元素就是字节）。越界形成的指针，即使尚未解引用，也只允许指向「末元素之后那一个」位置；再出去就是 UB。这与上一课「指针指向活对象」接上：数组提供一段连续活对象，指针在这段里移动。</p><p>多维数组作为参数写成 <code>T a[][N]</code> 时，内层长度必须出现在类型里，这样指针算术才知道一行多宽；最外层仍衰减。这常被误写成 <code>T **</code>，后者要求先有一层指针对象。本课把这一区别留给读声明的人：数组的数组连续，指针的指针中间有指针存储。后课结构体可以用「指针加长度」明确表达，避开衰减丢 \\(N\\) 的问题——那是用布局换回类型里失去的长度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>衰减让数组能廉价地交给函数：只传地址，不拷贝。代价是 callee 失去上界。任何「根据参数类型检查越界」在 C 里都做不到，除非把数组包进结构体、让类型带上 <code>N</code>。后课结构体布局会用到：结构体作为参数按值拷贝，其中的数组成员一起走，不衰减；一旦取出数组成员再传入另一个函数，衰减再次发生。</p><p>多维数组是「数组的数组」。<code>a[i]</code> 先得到一行（仍是数组），再衰减成该行首元素指针。不要把它想象成「指针的指针」：后者是两层独立对象，中间还有一次解引用。混用会在别名与释放时把所有权搞错。</p><p>字符串与 <code>char</code> 数组是同一规则的常用实例：字面量在静态区，传给函数时变成 <code>char *</code>，长度靠 <code>\\0</code> 而不是类型。这并不使数组「等于指针」——你仍不能对数组对象赋值，也不能让数组从函数按值返回整块。指针可以重新指向别的对象，数组名在非衰减上下文里仍是那一块连续存储。后课结构体把数组当成员嵌进去时，衰减被推迟到取出该成员的表达式，布局课会用到这条延迟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲柔性数组成员、变长数组的全部实现差异。对齐与填充下一课才出现。后课默认：数组是连续对象；多数表达式里名字变成首元素指针；作为参数传入时长度必须另给。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数组对象带长度；衰减后只剩指向首元素的指针。</li><li>函数参数 <code>T a[]</code> 与 <code>T *a</code> 等价，都不拷贝数组。</li><li><code>&amp;a</code> 与 <code>a</code> 类型不同，指针算术步长不同。</li><li>下一课把连续布局从数组推广到结构体字段。</li><li>出处：K&amp;R 数组与指针；ISO C 数组到指针的转换规则。</li></ul>',10))])}const T=r(E,[["render",h]]);export{C as __pageData,T as default};
